private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Check if there are any bytes left to decode
    if (!bb.hasRemaining()) {
        return i; // nothing to decode, return index unchanged
    }
    try {
        int b = bb.get() & 0xFF; // read unsigned byte
        // 1-byte ASCII (0xxxxxxx)
        if ((b & 0x80) == 0) {
            sb.append((char) b);
            return i + 1;
        }
        // 2-byte sequence (110xxxxx 10xxxxxx)
        if ((b & 0xE0) == 0xC0) {
            if (!bb.hasRemaining()) {
                sb.append('\uFFFD');
                return i + 1;
            }
            int b2 = bb.get() & 0xFF;
            if ((b2 & 0xC0) != 0x80) {
                sb.append('\uFFFD');
                return i + 1;
            }
            int codePoint = ((b & 0x1F) << 6) | (b2 & 0x3F);
            sb.append((char) codePoint);
            return i + 1;
        }
        // 3-byte sequence (1110xxxx 10xxxxxx 10xxxxxx)
        if ((b & 0xF0) == 0xE0) {
            if (bb.remaining() < 2) {
                sb.append('\uFFFD');
                return i + 1;
            }
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
                sb.append('\uFFFD');
                return i + 1;
            }
            int codePoint = ((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
            sb.append((char) codePoint);
            return i + 1;
        }
        // 4-byte sequence (11110xxx 10xxxxxx 10xxxxxx 10xxxxxx)
        if ((b & 0xF8) == 0xF0) {
            if (bb.remaining() < 3) {
                sb.append('\uFFFD');
                return i + 1;
            }
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            int b4 = bb.get() & 0xFF;
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80 || (b4 & 0xC0) != 0x80) {
                sb.append('\uFFFD');
                return i + 1;
            }
            int codePoint = ((b & 0x07) << 18)
                          | ((b2 & 0x3F) << 12)
                          | ((b3 & 0x3F) << 6)
                          | (b4 & 0x3F);
            // Convert to surrogate pair
            codePoint -= 0x10000;
            char high = (char) ((codePoint >> 10) + 0xD800);
            char low = (char) ((codePoint & 0x3FF) + 0xDC00);
            sb.append(high).append(low);
            return i + 1;
        }
        // Invalid leading byte
        sb.append('\uFFFD');
        return i + 1;
    } catch (Exception e) {
        // In case of any unexpected exception, append replacement char
        sb.append('\uFFFD');
        return i + 1;
    }
}

