private void enlarge(final int size){
    if (size <= 0) {
        return;
    }
    try {
        // Allocate a new buffer with additional capacity
        byte[] newBuf = new byte[this.buf.length + size];
        // Copy existing data into the new buffer
        System.arraycopy(this.buf, 0, newBuf, 0, this.buf.length);
        // Replace the old buffer with the enlarged one
        this.buf = newBuf;
    } catch (OutOfMemoryError e) {
        throw new RuntimeException("Unable to enlarge byte vector to accommodate additional " + size + " bytes", e);
    }
}

