@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        return;
    }
    // Add all vertices from the map to the target graph
    for (V vertex : resultMap.values()) {
        if (vertex == null) {
            continue;
        }
        if (!target.containsVertex(vertex)) {
            target.addVertex(vertex);
        }
    }

    // Build a list of vertices in insertion order
    List<V> vertices = new ArrayList<>(resultMap.values());
    if (vertices.size() < 2) {
        return; // Not enough vertices for a bipartite graph
    }

    // Partition the vertices into two sets arbitrarily (e.g., by odd/even indices)
    List<V> leftSet = new ArrayList<>();
    List<V> rightSet = new ArrayList<>();
    for (int i = 0; i < vertices.size(); i++) {
        V v = vertices.get(i);
        if (v == null) {
            continue;
        }
        if (i % 2 == 0) {
            leftSet.add(v);
        } else {
            rightSet.add(v);
        }
    }

    // Create all possible edges between leftSet and rightSet
    for (V u : leftSet) {
        for (V v : rightSet) {
            if (u == null || v == null || u.equals(v)) {
                continue;
            }
            // Add edge only if it does not already exist
            if (!target.containsEdge(u, v)) {
                target.addEdge(u, v);
            }
        }
    }
}

