public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("OutputStream cannot be null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema cannot be null");
    }
    if (message == null) {
        throw new NullPointerException("Message cannot be null");
    }
    // Calculate the serialized size of the message
    int messageSize = schema.getSerializedSize(message);
    // Create a CodedOutputStream for easier varint handling
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    // Write the length prefix as a varint
    cos.writeRawVarint32(messageSize);
    // Serialize the message itself
    schema.write(message, cos);
    cos.flush();
    return messageSize;
}

