public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType paramType = (ParameterizedType) genericType;
    Type[] args = paramType.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];

    // Attempt to build a mapping from type variables to actual types for the targetType
    Type raw = paramType.getRawType();
    if (!(raw instanceof Class<?>)) {
        return null;
    }
    Class<?> rawClass = (Class<?>) raw;
    Map<TypeVariable<?>, Type> typeVarAssigns = getTypeVariableMap(targetType, rawClass);
    if (typeVarAssigns == null) {
        return null;
    }

    for (int i = 0; i < args.length; i++) {
        Type arg = args[i];
        Class<?> resolved = null;

        if (arg instanceof Class<?>) {
            resolved = (Class<?>) arg;
        } else if (arg instanceof ParameterizedType) {
            Type rt = ((ParameterizedType) arg).getRawType();
            if (rt instanceof Class<?>) {
                resolved = (Class<?>) rt;
            }
        } else if (arg instanceof TypeVariable<?>) {
            Type mapped = typeVarAssigns.get(arg);
            if (mapped instanceof Class<?>) {
                resolved = (Class<?>) mapped;
            } else if (mapped instanceof ParameterizedType) {
                Type rt = ((ParameterizedType) mapped).getRawType();
                if (rt instanceof Class<?>) {
                    resolved = (Class<?>) rt;
                }
            }
        }

        if (resolved == null) {
            return null;
        }
        result[i] = resolved;
    }

    return result;
}

/**
 * Builds a map of type variable assignments for {@code target}
 * when interpreted as an instantiation of {@code base}.
 *
 * @return a map from the type variables of {@code base} to the concrete
 *         types used by {@code target}, or {@code null} if {@code target}
 *         does not implement/extend {@code base}.
 */
private static Map<TypeVariable<?>, Type> getTypeVariableMap(Class<?> target, Class<?> base) {
    // Direct check
    if (target == base) {
        TypeVariable<?>[] vars = base.getTypeParameters();
        Map<TypeVariable<?>, Type> map = new HashMap<>();
        for (TypeVariable<?> tv : vars) {
            map.put(tv, tv);
        }
        return map;
    }

    // Search interfaces
    for (Type iface : target.getGenericInterfaces()) {
        if (iface instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) iface;
            Class<?> raw = (Class<?>) pt.getRawType();
            if (raw == base) {
                return buildMapping(raw, pt);
            } else {
                Map<TypeVariable<?>, Type> sub = getTypeVariableMap(raw, base);
                if (sub != null) {
                    Map<TypeVariable<?>, Type> mapping = buildMapping(raw, pt);
                    // Resolve mapping through sub
                    for (Map.Entry<TypeVariable<?>, Type> e : mapping.entrySet()) {
                        Type t = e.getValue();
                        if (t instanceof TypeVariable<?> && sub.containsKey(t)) {
                            mapping.put(e.getKey(), sub.get(t));
                        }
                    }
                    return mapping;
                }
            }
        } else if (iface instanceof Class<?>) {
            Class<?> ifaceCls = (Class<?>) iface;
            if (ifaceCls == base) {
                return getTypeVariableMap(ifaceCls, base);
            } else {
                Map<TypeVariable<?>, Type> sub = getTypeVariableMap(ifaceCls, base);
                if (sub != null) {
                    return sub;
                }
            }
        }
    }

    // Search superclass
    Type sup = target.getGenericSuperclass();
    if (sup != null) {
        if (sup instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) sup;
            Class<?> raw = (Class<?>) pt.getRawType();
            if (raw == base) {
                return buildMapping(raw, pt);
            } else {
                Map<TypeVariable<?>, Type> sub = getTypeVariableMap(raw, base);
                if (sub != null) {
                    Map<TypeVariable<?>, Type> mapping = buildMapping(raw, pt);
                    for (Map.Entry<TypeVariable<?>, Type> e : mapping.entrySet()) {
                        Type t = e.getValue();
                        if (t instanceof TypeVariable<?> && sub.containsKey(t)) {
                            mapping.put(e.getKey(), sub.get(t));
                        }
                    }
                    return mapping;
                }
            }
        } else if (sup instanceof Class<?>) {
            Class<?> supCls = (Class<?>) sup;
            if (supCls == base) {
                return getTypeVariableMap(supCls, base);
            } else {
                Map<TypeVariable<?>, Type> sub = getTypeVariableMap(supCls, base);
                if (sub != null) {
                    return sub;
                }
            }
        }
    }

    return null;
}

/**
 * Builds a mapping between the type variables declared by {@code raw}
 * and the actual type arguments supplied by {@code pt}.
 */
private static Map<TypeVariable<?>, Type> buildMapping(Class<?> raw, ParameterizedType pt) {
    TypeVariable<?>[] vars = raw.getTypeParameters();
    Type[] args = pt.getActualTypeArguments();
    Map<TypeVariable<?>, Type> map = new HashMap<>();
    for (int i = 0; i < vars.length; i++) {
        map.put(vars[i], args[i]);
    }
    return map;
}

