void insertBefore(Bucket bucket){
    if (bucket == null) {
        throw new IllegalArgumentException("bucket cannot be null");
    }

    // If this bucket is already linked in the list, detach it first
    if (this.prev != null) {
        this.prev.next = this.next;
    }
    if (this.next != null) {
        this.next.prev = this.prev;
    }

    // Insert this before the specified bucket
    this.prev = bucket.prev;
    this.next = bucket;

    if (bucket.prev != null) {
        bucket.prev.next = this;
    }

    bucket.prev = this;
}

