        return null;
    }
    byte[] result = new byte[array.length];
    for (int i = 0; i < array.length; i++) {
        Byte b = array[i];
        if (b == null) {
            throw new NullPointerException("Array element at index " + i + " is null");
        }
        result[i] = b.byteValue();
    }
    return result;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if (dayStep <= 0) {
        return timeBucket;
    }
    long year = timeBucket / 10000L;
    long month = (timeBucket / 100L) % 100L;
    long day = timeBucket % 100L;
    long bucketDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + bucketDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (len < 0) {
        throw new IndexOutOfBoundsException("len is negative");
    }
    final int strLen = str.length();
    if (index < 0 || index > strLen) {
        throw new IndexOutOfBoundsException("index out of bounds");
    }
    int end = index + len;
    if (end < index) { // overflow
        throw new IndexOutOfBoundsException("int overflow");
    }
    if (end > strLen) {
        throw new IndexOutOfBoundsException("index+len exceeds string length");
    }

    int bytes = 0;
    int i = index;
    while (i < end) {
        int cp = str.codePointAt(i);
        if (cp <= 0x7F) {
            bytes += 1;
        } else if (cp <= 0x7FF) {
            bytes += 2;
        } else if (cp <= 0xFFFF) {
            bytes += 3;
        } else {
            bytes += 4;
        }
        i += Character.charCount(cp);
    }
    return bytes;
}

public static <T> java.util.List<T> asList(T[] a) {
