        public T get(int index) {
            if (index < 0 || index >= a.length) {
                throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + a.length);
            }
            return a[index];
        }
        public int size() {
            return a.length;
        }
        public T set(int index, T element) {
            if (index < 0 || index >= a.length) {
                throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + a.length);
            }
            T old = a[index];
            a[index] = element;
            return old;
        }
    };
}

public boolean remove(int val) {
    if (data == null || size == 0) {
        return false;
    }
    for (int i = 0; i < size; i++) {
        if (data[i] == val) {
            // Shift elements left to fill the gap
            int remaining = size - i - 1;
            if (remaining > 0) {
                System.arraycopy(data, i + 1, data, i, remaining);
            }
            size--;
            if (data.length > 0) {
                data[size] = 0; // Optional: clear the duplicate tail element
            }
            return true;
        }
    }
    return false;
}

