public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb){
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }
    if (str == null) {
        // Write a marker indicating a null string
        lb.writeInt(-1); // assume writeInt exists
        return lb;
    }
    // Encode the string into UTF‑8 bytes
    java.nio.ByteBuffer utf8Buf = java.nio.charset.StandardCharsets.UTF_8.encode(str);
    int byteLen = utf8Buf.remaining();
    // Write the length of the byte array
    lb.writeInt(byteLen); // assume writeInt exists
    // Prepare a byte array with the encoded data
    byte[] bytes = new byte[byteLen];
    utf8Buf.get(bytes);
    // Write the byte array into the buffer
    lb.write(bytes, 0, byteLen); // assume write(byte[],int,int) exists
    return lb;
}

