public static String findAndSubst(String key, Properties props) {
    if (props == null) {
        return null;
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Perform simple ${var} substitution using properties
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)}");
    java.util.regex.Matcher matcher = pattern.matcher(value);
    StringBuffer sb = new StringBuffer();
    while (matcher.find()) {
        String varName = matcher.group(1);
        String replacement = props.getProperty(varName);
        if (replacement == null) {
            replacement = "";
        }
        replacement = java.util.regex.Matcher.quoteReplacement(replacement);
        matcher.appendReplacement(sb, replacement);
    }
    matcher.appendTail(sb);
    String result = sb.toString();

    // Repeat substitution in case replacements contain further placeholders
    while (pattern.matcher(result).find()) {
        matcher = pattern.matcher(result);
        sb = new StringBuffer();
        while (matcher.find()) {
            String varName = matcher.group(1);
            String replacement = props.getProperty(varName);
            if (replacement == null) {
                replacement = "";
            }
            replacement = java.util.regex.Matcher.quoteReplacement(replacement);
            matcher.appendReplacement(sb, replacement);
        }
        matcher.appendTail(sb);
        result = sb.toString();
    }
    return result;
}

