public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null){
        throw new IllegalArgumentException("box cannot be null");
    }
    double minX = box.getMinX();
    double minY = box.getMinY();
    double maxX = box.getMaxX();
    double maxY = box.getMaxY();
    if (minX > maxX){
        throw new IllegalArgumentException("Box minX must be <= maxX");
    }
    if (minY > maxY){
        throw new IllegalArgumentException("Box minY must be <= maxY");
    }
    double midX = (minX + maxX) / 2.0;
    Box2D first = new Box2D(minX, minY, midX, maxY);
    Box2D second = new Box2D(midX, minY, maxX, maxY);
    return new Pair<>(first, second);
}

