public void readFrom(final InputStream in) throws IOException {
    // Read the entire input stream into a byte array
    java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
    byte[] buffer = new byte[8192];
    int read;
    while ((read = in.read(buffer)) != -1) {
        baos.write(buffer, 0, read);
    }
    byte[] data = baos.toByteArray();

    // Locate a byte[] field to hold the data
    java.lang.reflect.Field byteField = null;
    java.lang.reflect.Field intField = null;
    for (java.lang.reflect.Field f : this.getClass().getDeclaredFields()) {
        if (byteField == null && f.getType() == byte[].class) {
            byteField = f;
        }
        if (intField == null && f.getType() == int.class) {
            intField = f;
        }
    }
    try {
        if (byteField != null) {
            byteField.setAccessible(true);
            byteField.set(this, data);
        }
        if (intField != null) {
            intField.setAccessible(true);
            intField.setInt(this, 0); // reset read pointer to start
        }
    } catch (IllegalAccessException e) {
        throw new IOException("Failed to set buffer contents", e);
    }
}

