    }
    String lowerStr = str.toLowerCase(java.util.Locale.ROOT);
    for (String search : searchStrArray) {
        if (search == null || search.isEmpty()) {
            continue;
        }
        String lowerSearch = search.toLowerCase(java.util.Locale.ROOT);
        if (lowerStr.contains(lowerSearch)) {
            return true;
        }
    }
    return false;
}

public static int nextPrime(int desiredCapacity){
    int candidate = Math.max(2, desiredCapacity);
    while (true) {
        if (candidate == 2) {
            return 2;
        }
        if (candidate % 2 == 0) {
            candidate++;
            continue;
        }
        boolean isPrime = true;
        for (int i = 3; (long)i * i <= candidate; i += 2) {
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate++;
    }
}

