@Override public String readString() throws IOException {
    // Read a string value from the underlying input stream.
    // The string is prefixed with a 4-byte integer length in big‑endian order.
    // The string bytes are assumed to be encoded in UTF‑8.
    int length = in.readInt();
    if (length < 0) {
        throw new IOException("Negative string length: " + length);
    }
    byte[] bytes = new byte[length];
    int offset = 0;
    while (offset < length) {
        int count = in.read(bytes, offset, length - offset);
        if (count == -1) {
            throw new EOFException("Unexpected end of stream while reading string");
        }
        offset += count;
    }
    return new String(bytes, "UTF-8");
}

