    return -1;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> map = new HashMap<>();
    if(jsonObject == null){
        return map;
    }
    try{
        for(Map.Entry<String,JsonElement> entry : jsonObject.entrySet()){
            JsonElement elem = entry.getValue();
            Object value;
            if(elem.isJsonPrimitive()){
                JsonPrimitive prim = elem.getAsJsonPrimitive();
                if(prim.isString()){
                    value = prim.getAsString();
                }else if(prim.isNumber()){
                    value = prim.getAsNumber();
                }else if(prim.isBoolean()){
                    value = prim.getAsBoolean();
                }else{
                    value = prim.getAsString();
                }
            }else if(elem.isJsonArray()){
                value = elem.getAsJsonArray(); // keep the array as is
            }else if(elem.isJsonObject()){
                value = elem.getAsJsonObject(); // keep nested object
            }else{
                value = null;
            }
            map.put(entry.getKey(), value);
        }
        if(map.containsKey("ats")){
            map.put("ats", "set");
        }
    }catch(Exception e){
        // ignore errors and return what has been built so far
    }
    return map;
}

