public final byte[] toByteArray() {
    try {
        java.lang.reflect.Field[] fields = this.getClass().getDeclaredFields();
        java.util.List<byte[]> parts = new java.util.ArrayList<>();
        int totalSize = 0;
        for (java.lang.reflect.Field f : fields) {
            f.setAccessible(true);
            Object value = f.get(this);
            if (value == null) continue;
            if (value instanceof byte[]) {
                byte[] data = (byte[]) value;
                if (data.length > 0) {
                    parts.add(data);
                    totalSize += data.length;
                }
            } else if (value instanceof java.nio.ByteBuffer) {
                java.nio.ByteBuffer bb = (java.nio.ByteBuffer) value;
                if (bb.hasRemaining()) {
                    int len = bb.remaining();
                    byte[] data = new byte[len];
                    bb.mark();
                    bb.get(data);
                    bb.reset();
                    parts.add(data);
                    totalSize += len;
                }
            } else if (value instanceof java.util.Collection) {
                java.util.Collection<?> col = (java.util.Collection<?>) value;
                for (Object elem : col) {
                    if (elem instanceof byte[]) {
                        byte[] data = (byte[]) elem;
                        if (data.length > 0) {
                            parts.add(data);
                            totalSize += data.length;
                        }
                    } else if (elem instanceof java.nio.ByteBuffer) {
                        java.nio.ByteBuffer bb = (java.nio.ByteBuffer) elem;
                        if (bb.hasRemaining()) {
                            int len = bb.remaining();
                            byte[] data = new byte[len];
                            bb.mark();
                            bb.get(data);
                            bb.reset();
                            parts.add(data);
                            totalSize += len;
                        }
                    }
                }
            }
        }
        if (totalSize == 0) return new byte[0];
        byte[] result = new byte[totalSize];
        int offset = 0;
        for (byte[] part : parts) {
            System.arraycopy(part, 0, result, offset, part.length);
            offset += part.length;
        }
        return result;
    } catch (Exception e) {
        throw new RuntimeException("Failed to convert to byte array", e);
    }
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int i = 0;
    int len = str.length();
    while (i < len) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i += 2;
                    break;
                case 'f':
                    sb.append('\f');
                    i += 2;
                    break;
                case 'n':
                    sb.append('\n');
                    i += 2;
                    break;
                case 'r':
                    sb.append('\r');
                    i += 2;
                    break;
                case 't':
                    sb.append('\t');
                    i += 2;
                    break;
                case '\"':
                    sb.append('\"');
                    i += 2;
                    break;
                case '\'':
                    sb.append('\'');
                    i += 2;
                    break;
                case '\\':
                    sb.append('\\');
                    i += 2;
                    break;
                case 'u':
                    if (i + 6 > len) {
                        throw new IllegalArgumentException("Invalid Unicode escape sequence at position " + i);
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid Unicode escape sequence: \\u" + hex, e);
                    }
                    i += 6;
                    break;
                default:
                    // Unrecognized escape: treat as literal next char
                    sb.append(next);
                    i += 2;
                    break;
            }
        } else {
            sb.append(c);
            i++;
        }
    }
    return sb.toString();
}

