private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    if (array == null) {
        if (newArrayComponentType == null) {
            throw new IllegalArgumentException("newArrayComponentType must not be null when array is null");
        }
        return java.lang.reflect.Array.newInstance(newArrayComponentType, 1);
    }
    Class<?> arrayClass = array.getClass();
    if (!arrayClass.isArray()) {
        throw new IllegalArgumentException("The provided object is not an array");
    }
    int oldLen = java.lang.reflect.Array.getLength(array);
    Class<?> componentType = arrayClass.getComponentType();
    Class<?> targetComponentType = newArrayComponentType != null ? newArrayComponentType : componentType;
    Object newArray = java.lang.reflect.Array.newInstance(targetComponentType, oldLen + 1);
    for (int i = 0; i < oldLen; i++) {
        java.lang.reflect.Array.set(newArray, i, java.lang.reflect.Array.get(array, i));
    }
    return newArray;
}

private int computeBinaryLog(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be positive");
    }
    // Integer.numberOfLeadingZeros returns the number of zero bits preceding the highest-order
    // one-bit in the two's complement representation of the integer. For a positive int,
    // the highest set bit position is 31 - leadingZeros. The floor of log2(n) is this position.
    // Adding 1 gives the number of bits required to represent n.
    return 32 - Integer.numberOfLeadingZeros(n);
}

