    javax.json.JsonObjectBuilder builder = javax.json.Json.createObjectBuilder();
    if (properties == null) {
        return builder.build();
    }
    for (KeyStringValuePair pair : properties) {
        if (pair == null) {
            continue;
        }
        String key = pair.getKey();
        if (key == null) {
            continue;
        }
        String value = pair.getValue();
        if (value != null) {
            builder.add(key, value);
        } else {
            builder.addNull(key);
        }
    }
    return builder.build();
}

protected int removeUnusedNodes(){
    Category root = getRoot();
    if (root == null) return 0;
    int[] removed = new int[]{0};
    processNode(root, removed, new java.util.HashSet<Category>());
    return removed[0];
}

private boolean processNode(Category node, int[] removed, java.util.Set<Category> visited){
    if (!visited.add(node)) return false;
    boolean selfActive = node.isActive();
    java.util.List<Category> children = node.getChildren();
    if (children == null) return selfActive;
    java.util.Iterator<Category> it = children.iterator();
    while (it.hasNext()){
        Category child = it.next();
        boolean childHasActive = processNode(child, removed, visited);
        if (!childHasActive){
            it.remove();
            removed[0]++;
        }
    }
    return selfActive || !children.isEmpty();
}

