final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    if (constantPoolEntryIndex <= 0){
        throw new IllegalArgumentException("constantPoolEntryIndex must be > 0");
    }
    if (classFileBuffer == null){
        throw new IllegalStateException("classFileBuffer not initialized");
    }
    // skip magic (4), minor_version (2), major_version (2)
    int pos = 8;
    // read constant_pool_count
    if (classFileBuffer.length < pos + 2){
        throw new IndexOutOfBoundsException("class file too short");
    }
    int cpCount = ((classFileBuffer[pos] & 0xFF) << 8) | (classFileBuffer[pos + 1] & 0xFF);
    pos += 2;
    int index = 1;
    while (index < cpCount){
        if (pos >= classFileBuffer.length){
            throw new IndexOutOfBoundsException("class file truncated");
        }
        int tag = classFileBuffer[pos] & 0xFF;
        pos++;
        switch (tag){
            case 1: // CONSTANT_Utf8
                if (index == constantPoolEntryIndex){
                    int length = ((classFileBuffer[pos] & 0xFF) << 8) | (classFileBuffer[pos + 1] & 0xFF);
                    pos += 2;
                    if (classFileBuffer.length < pos + length){
                        throw new IndexOutOfBoundsException("class file truncated while reading Utf8");
                    }
                    String s = new String(classFileBuffer, pos, length, java.nio.charset.StandardCharsets.UTF_8);
                    if (charBuffer != null){
                        if (charBuffer.length < s.length()){
                            throw new IllegalArgumentException("charBuffer too small");
                        }
                        s.getChars(0, s.length(), charBuffer, 0);
                    }
                    return s;
                } else {
                    int length = ((classFileBuffer[pos] & 0xFF) << 8) | (classFileBuffer[pos + 1] & 0xFF);
                    pos += 2 + length;
                }
                break;
            case 3: // CONSTANT_Integer
            case 4: // CONSTANT_Float
                pos += 4;
                break;
            case 5: // CONSTANT_Long
            case 6: // CONSTANT_Double
                pos += 8;
                index++; // long/double occupies two entries
                break;
            case 7: // CONSTANT_Class
            case 8: // CONSTANT_String
            case 16: // CONSTANT_MethodType
            case 19: // CONSTANT_Module
            case 20: // CONSTANT_Package
                pos += 2;
                break;
            case 9: // Fieldref
            case 10: // Methodref
            case 11: // InterfaceMethodref
            case 12: // NameAndType
            case 18: // CONSTANT_Dynamic
            case 17: // CONSTANT_InvokeDynamic
                pos += 4;
                break;
            case 15: // CONSTANT_MethodHandle
                pos += 3;
                break;
            default:
                throw new IllegalStateException("Unknown constant pool tag: " + tag);
        }
        index++;
    }
    throw new IllegalArgumentException("Invalid constantPoolEntryIndex: " + constantPoolEntryIndex);
}

