public static long factorial(int n){
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    long result = 1L;
    for (int i = 2; i <= n; i++) {
        if (Long.MAX_VALUE / i < result) {
            throw new ArithmeticException("Factorial value overflows long");
        }
        result *= i;
    }
    return result;
}

