public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    if(byteLength < 0){
        throw new IllegalArgumentException("byteLength must be non–negative");
    }
    if(byteLength == 0){
        return this;
    }
    // Ensure the underlying byte array has enough space
    if(size + byteLength > data.length){
        int newCap = Math.max(data.length * 2, size + byteLength);
        byte[] newData = new byte[newCap];
        System.arraycopy(data, 0, newData, 0, size);
        data = newData;
    }
    if(byteArrayValue == null){
        // Fill with zero bytes
        for(int i = 0; i < byteLength; i++){
            data[size + i] = 0;
        }
    } else {
        if(byteOffset < 0 || byteOffset > byteArrayValue.length){
            throw new IllegalArgumentException("byteOffset out of bounds");
        }
        if(byteLength > byteArrayValue.length - byteOffset){
            throw new IllegalArgumentException("byteLength exceeds array bounds");
        }
        System.arraycopy(byteArrayValue, byteOffset, data, size, byteLength);
    }
    size += byteLength;
    return this;
}

