    if (v == null || v.isEmpty()) {
        return sum;
    }
    for (V vertex : v) {
        List<Edge<V>> edges = incomingEdges.get(vertex);
        if (edges != null) {
            for (Edge<V> e : edges) {
                sum += e.getWeight();
            }
        }
    }
    return sum;
}

