protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null){
        throw new IllegalArgumentException("tour must not be null");
    }
    if (graph == null){
        throw new IllegalArgumentException("graph must not be null");
    }
    if (tour.isEmpty()){
        return null;
    }
    List<E> edgePath = new ArrayList<>();
    List<V> vertexPath = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);

    // start with an arbitrary edge
    E firstEdge = remaining.iterator().next();
    remaining.remove(firstEdge);
    V startVertex = graph.getEdgeSource(firstEdge);
    V currentVertex = graph.getEdgeTarget(firstEdge);

    vertexPath.add(startVertex);
    edgePath.add(firstEdge);
    vertexPath.add(currentVertex);
    currentVertex = currentVertex;

    // iterate until all edges are consumed
    while (!remaining.isEmpty()){
        boolean found = false;
        Iterator<E> it = remaining.iterator();
        while (it.hasNext()){
            E e = it.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(currentVertex)){
                edgePath.add(e);
                vertexPath.add(tgt);
                currentVertex = tgt;
                it.remove();
                found = true;
                break;
            } else if (tgt.equals(currentVertex)){
                edgePath.add(e);
                vertexPath.add(src);
                currentVertex = src;
                it.remove();
                found = true;
                break;
            }
        }
        if (!found){
            throw new IllegalArgumentException("Edges do not form a continuous tour");
        }
    }

    double weight = 0.0;
    for (E e : edgePath){
        weight += graph.getEdgeWeight(e);
    }

    return new GraphPathImpl<>(graph, vertexPath.get(0), currentVertex, weight, vertexPath, edgePath);
}

