    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null) {
        target = new HashSet<>();
        bucketsByLabel.set(0, target);
    }
    for (Integer v : source) {
        target.add(v);
        if (v >= 0 && v < labels.size()) {
            labels.set(v, 0);
        }
    }
    if (minLabel != 0) {
        source.clear(); // clear the source bucket only if it's not bucket 0
    }
}

