    if (node == null) {
        return false;
    }
    // update the links of the adjacent nodes
    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;
    if (prev != null) {
        prev.next = next;
    } else {
        // node was head
        first = next;
    }
    if (next != null) {
        next.prev = prev;
    } else {
        // node was tail
        last = prev;
    }
    // detach the node
    node.prev = null;
    node.next = null;
    if (node.entry != null) {
        node.entry = null;
    }
    // adjust size
    size--;
    return true;
}

