private List<Integer> computeLowerBounds(List<K> keys) {
    if (keys == null) {
        throw new IllegalArgumentException("keys list must not be null");
    }
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (K keyObj : keys) {
        if (keyObj == null) {
            lowerBounds.add(null);
            continue;
        }
        int key;
        try {
            key = ((Number) keyObj).intValue();
        } catch (ClassCastException e) {
            lowerBounds.add(null);
            continue;
        }
        int maxLower = Integer.MIN_VALUE;
        boolean found = false;
        for (K otherObj : keys) {
            if (otherObj == null) {
                continue;
            }
            int other;
            try {
                other = ((Number) otherObj).intValue();
            } catch (ClassCastException e) {
                continue;
            }
            if (other < key && other > maxLower) {
                maxLower = other;
                found = true;
            }
        }
        if (found) {
            lowerBounds.add(maxLower);
        } else {
            lowerBounds.add(null);
        }
    }
    return lowerBounds;
}

