    String types;
    if (descriptor.charAt(0) == '('){
        int end = descriptor.indexOf(')');
        if (end == -1){
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }
        types = descriptor.substring(1, end);
    } else {
        types = descriptor;
    }
    int i = 0;
    while (i < types.length()){
        char c = types.charAt(i);
        int slots = 1;
        if (c == 'J' || c == 'D'){
            slots = 2;
        }
        while (c == '['){
            i++;
            if (i >= types.length()){
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            c = types.charAt(i);
        }
        if (c == 'L'){
            int semicolon = types.indexOf(';', i);
            if (semicolon == -1){
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            i = semicolon + 1;
        } else if ("BCDFIJSZ".indexOf(c) >= 0){
            i++;
        } else {
            throw new IllegalArgumentException("Unknown type code: " + c + " in descriptor " + descriptor);
        }
        for (int s = 0; s < slots; s++){
            // pop a stack slot; placeholder for actual stack operation
            popStackSlot();
        }
    }
}

private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> bounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return bounds;
    }
    List<K> sorted = new ArrayList<>(keys);
    try {
        sorted.sort(null); // natural ordering, requires K implements Comparable
    } catch (ClassCastException e) {
        // If keys cannot be naturally ordered, return empty bounds list
        return bounds;
    }
    for (K key : keys) {
        int idx = Collections.binarySearch(sorted, key);
        if (idx < 0) {
            idx = -idx - 1; // lower bound index
        }
        bounds.add(idx);
    }
    return bounds;
}

public static String encodeTemplateNames(String s){
    if (s == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '{') {
            sb.append("%7B");
        } else if (c == '}') {
            sb.append("%7D");
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

public static boolean equals(Point2D p1,Point2D p2){
    if (p1 == p2) {
        return true;
    }
    if (p1 == null || p2 == null) {
        return false;
    }
    final double tolerance = 1e-9;
    double dx = p1.getX() - p2.getX();
    double dy = p1.getY() - p2.getY();
    return Math.abs(dx) <= tolerance && Math.abs(dy) <= tolerance;
}

