public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        throw new IllegalArgumentException("path must not be null");
    }
    if (relativePath == null) {
        throw new IllegalArgumentException("relativePath must not be null");
    }

    // Determine base directory from the given path.
    String base = path;
    int lastSlash = base.lastIndexOf('/');
    if (lastSlash >= 0) {
        // Keep the trailing slash for proper concatenation
        base = base.substring(0, lastSlash + 1);
    } else {
        base = "";
    }

    // Combine base with the relative path
    String combined = base + relativePath;

    // Normalize the combined path
    String[] parts = combined.split("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();
    String prefix = combined.startsWith("/") ? "/" : "";

    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
            // If stack is empty and part is "..", we ignore for absolute paths.
            continue;
        }
        stack.push(part);
    }

    // Build the final path string
    java.lang.StringBuilder sb = new java.lang.StringBuilder();
    sb.append(prefix);
    java.util.Iterator<String> it = stack.descendingIterator();
    while (it.hasNext()) {
        sb.append(it.next());
        if (it.hasNext()) {
            sb.append("/");
        }
    }
    return sb.toString();
}

