static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return new String[0];
    }
    int nonNullCount = 0;
    boolean allNonNull = true;
    for (Object o : array) {
        if (o == null) {
            allNonNull = false;
        } else {
            nonNullCount++;
        }
    }
    if (allNonNull && array instanceof String[]) {
        return (String[]) array;
    }
    if (!allNonNull) {
        String[] result = new String[nonNullCount];
        int idx = 0;
        for (Object o : array) {
            if (o != null) {
                result[idx++] = o instanceof String ? (String) o : o.toString();
            }
        }
        return result;
    }
    // all non-null but original array not String[]
    String[] result = new String[array.length];
    for (int i = 0; i < array.length; i++) {
        Object o = array[i];
        result[i] = o instanceof String ? (String) o : o.toString();
    }
    return result;
}

public static int indexOfExtension(String filename){
