    int lastDot = filename.lastIndexOf('.');
    if (lastDot == -1) { return -1; }
    int lastSep = indexOfLastSeparator(filename);
    if (lastSep >= lastDot) { return -1; }
    return lastDot;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    if (expiredThreshold < 0) {
        // Negative threshold is treated as already expired
        return true;
    }
    long currentTime = System.currentTimeMillis();
    // Prevent overflow when subtracting timestamps
    long elapsed;
    try {
        elapsed = Math.subtractExact(currentTime, timestamp);
    } catch (ArithmeticException e) {
        // If overflow occurs, consider it expired
        return true;
    }
    return elapsed > expiredThreshold;
}

public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    if (str == null || substring == null) {
        return false;
    }
    int strLen = str.length();
    int subLen = substring.length();
    if (index < 0) {
        return false;
    }
    if (index + subLen > strLen) {
        return false;
    }
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

